-- 会话 A（RR）
BEGIN;
SELECT * FROM account WHERE id BETWEEN 1 AND 10;          -- 快照读，生成 ReadView

-- 会话 B
INSERT INTO account(id, balance) VALUES (5, 100); COMMIT;

-- 会话 A
SELECT * FROM account WHERE id BETWEEN 1 AND 10;          -- 仍看不到 id=5（MVCC）
SELECT * FROM account WHERE id BETWEEN 1 AND 10 FOR UPDATE; -- 当前读，能看到 id=5，并加临键锁
COMMIT;

CREATE TABLE t_order (
  id BIGINT PRIMARY KEY, user_id BIGINT, phone VARCHAR(20), status TINYINT,
  create_time DATETIME,
  KEY idx_phone (phone),
  KEY idx_user_status_time (user_id, status, create_time)
);

-- ❌ 隐式转换：phone 是 varchar，参数是数字
EXPLAIN SELECT * FROM t_order WHERE phone = 13800000000;      -- type=ALL
-- ✅
EXPLAIN SELECT * FROM t_order WHERE phone = '13800000000';    -- type=ref

-- ❌ 函数作用在列上
EXPLAIN SELECT * FROM t_order WHERE DATE(create_time) = '2026-10-01';
-- ✅ 改成范围
EXPLAIN SELECT * FROM t_order
 WHERE create_time >= '2026-10-01' AND create_time < '2026-10-02';

-- ❌ 跳过最左列
EXPLAIN SELECT * FROM t_order WHERE status = 1;
-- ✅ 最左前缀
EXPLAIN SELECT * FROM t_order WHERE user_id = 42 AND status = 1;

CREATE TABLE t_user (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(50), age INT, city VARCHAR(50),
  KEY idx_name_age (name, age)
);

-- 回表：二级索引找到 id，再回聚簇索引取 city
EXPLAIN SELECT * FROM t_user WHERE name = '张三';
-- 覆盖索引：name, age, id 都在 idx_name_age 中，Extra: Using index
EXPLAIN SELECT id, name, age FROM t_user WHERE name = '张三';

-- 深分页优化：先用覆盖索引查 id，再关联回表
SELECT u.* FROM t_user u
JOIN (SELECT id FROM t_user ORDER BY id LIMIT 1000000, 20) t ON u.id = t.id;

-- 查看与设置隔离级别（MySQL 8.0）
SELECT @@transaction_isolation;
SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;

-- 不可重复读演示（RC 下）
-- 会话 A
BEGIN;
SELECT balance FROM account WHERE id = 1;   -- 100
-- 会话 B
UPDATE account SET balance = 200 WHERE id = 1; COMMIT;
-- 会话 A
SELECT balance FROM account WHERE id = 1;   -- RC：200（不可重复读）；RR：仍为 100
COMMIT;

-- 1. 函数 → 范围
-- ❌ WHERE YEAR(create_time) = 2026
SELECT id FROM t_order WHERE create_time >= '2026-01-01' AND create_time < '2027-01-01';

-- 2. 函数索引（MySQL 8.0.13+）
ALTER TABLE t_user ADD INDEX idx_lower_email ((LOWER(email)));
SELECT * FROM t_user WHERE LOWER(email) = 'a@b.com';

-- 3. 统计信息过期导致选错索引
ANALYZE TABLE t_order;
EXPLAIN SELECT * FROM t_order WHERE user_id = 42 AND status = 1;

-- 4. 前导模糊 → 全文索引或搜索引擎
ALTER TABLE t_article ADD FULLTEXT INDEX ft_title (title) WITH PARSER ngram;
SELECT * FROM t_article WHERE MATCH(title) AGAINST('面试' IN BOOLEAN MODE);
